const fs = require('fs');
const path = require('path');
const META_FILE = '/app/.openclaw/memory/dream-meta.json';
const SESSIONS_DIR = '/app/.openclaw/agents/main/sessions';
const LOCK_FILE = '/app/.openclaw/memory/dream.lock';
const LOCK_TTL_HOURS = 2;

let meta = { last_run: null };
try { meta = JSON.parse(fs.readFileSync(META_FILE, 'utf8')); } catch {}

let hoursSince = Infinity;
if (meta.last_run) hoursSince = (Date.now() - new Date(meta.last_run).getTime()) / 3600000;
const timeOk = hoursSince >= 24;

const lastRunTs = meta.last_run ? new Date(meta.last_run).getTime() : 0;
let newSessions = 0;
try {
  newSessions = fs.readdirSync(SESSIONS_DIR)
    .filter(f => f.endsWith('.jsonl'))
    .filter(f => { try { return fs.statSync(path.join(SESSIONS_DIR, f)).mtimeMs > lastRunTs; } catch { return false; } }).length;
} catch {}
const sessionsOk = newSessions > 3;

let activeSession = false;
try {
  const sessJson = JSON.parse(fs.readFileSync(path.join(SESSIONS_DIR, 'sessions.json'), 'utf8'));
  for (const [, sess] of Object.entries(sessJson)) {
    if (Date.now() - (sess.updatedAt || 0) < 60000) { activeSession = true; break; }
  }
} catch {}

// Gate 3: Distributed lock (prevents concurrent M30 runs)
let lockAcquired = false;
let lockReason = null;
try {
  const lockStat = fs.statSync(LOCK_FILE);
  const lockAgeHours = (Date.now() - lockStat.mtimeMs) / 3600000;
  if (lockAgeHours > LOCK_TTL_HOURS) {
    // Stale lock — safe to overwrite and acquire
    fs.writeFileSync(LOCK_FILE, JSON.stringify({ pid: process.pid, ts: new Date().toISOString(), stale_overwrite: true }));
    lockAcquired = true;
  } else {
    lockReason = 'Lock held by concurrent run (age: ' + lockAgeHours.toFixed(2) + 'h)';
  }
} catch (e) {
  if (e.code === 'ENOENT') {
    // No lock — acquire
    try {
      fs.mkdirSync(path.dirname(LOCK_FILE), { recursive: true });
      fs.writeFileSync(LOCK_FILE, JSON.stringify({ pid: process.pid, ts: new Date().toISOString() }));
      lockAcquired = true;
    } catch (writeErr) {
      lockReason = 'Failed to acquire lock: ' + writeErr.message;
    }
  } else {
    lockReason = 'Lock stat error: ' + e.message;
  }
}

const shouldRun = timeOk && sessionsOk && !activeSession && lockAcquired;
const skipReason = !timeOk ? 'Not enough time since last run'
  : !sessionsOk ? 'Need >3 new sessions'
  : activeSession ? 'Active session detected'
  : !lockAcquired ? (lockReason || 'Could not acquire lock')
  : null;

return [{ json: { shouldRun, timeOk, sessionsOk, activeSession, lockAcquired, lockReason,
  hoursSince: Math.round(hoursSince * 10) / 10, newSessions, lastRun: meta.last_run,
  skipReason, lockFile: LOCK_FILE } }];

const { execSync } = require('child_process');
const fs = require('fs');
const LOCK_FILE = '/app/.openclaw/memory/dream.lock';
let stdout = '';
let exitCode = -1;
try {
  stdout = execSync('timeout 600 node /app/.openclaw/extensions/dream/dream.js 2>&1', {
    timeout: 610000,
    maxBuffer: 1024 * 1024
  }).toString();
  exitCode = 0;
} catch (e) {
  stdout = (e.stdout || '') + (e.stderr || '') + e.message;
  exitCode = e.status || 1;
}
// Release lock on success or failure
try { fs.unlinkSync(LOCK_FILE); } catch {}
return [{ json: { stdout, exitCode } }];

const stdout = $input.first().json.stdout || '';
const exitCode = $input.first().json.exitCode;
const success = exitCode === 0;
let result = {};
const lines = stdout.split('\n').reverse();
for (const line of lines) {
  try {
    const p = JSON.parse(line.trim());
    if (p && typeof p === 'object' && !Array.isArray(p)) { result = p; break; }
  } catch {}
}
return [{ json: { success, exitCode, ...result, stdout_tail: stdout.split('\n').slice(-8).join('\n') } }];

const dream = $input.first().json || {};
const items = $input.all();
return [{ json: {
  workflow_name: $workflow.name,
  execution_id: String($execution.id),
  status: dream.success ? 'completed' : (dream.skipped ? 'skipped' : 'failed'),
  dream_result: { last_run: dream.last_run, sessions_processed: dream.sessions_processed, chunks_added: dream.chunks_added, skipped: dream.skipped, skip_reason: dream.skip_reason, error: dream.error },
  items_count: items.length,
  finished_at: new Date().toISOString(),
  service_identity: 'n8n-workflows',
  metadata: { node_count: $workflow.nodes?.length || 0, job: 'M30-Dream' }
}}];

const input = .first().json;
const fs = require('fs');
const LOCK_FILE = '/app/.openclaw/memory/dream.lock';
// Release lock on skip (we acquired it before deciding to skip)
if (input.lockAcquired) {
  try { fs.unlinkSync(LOCK_FILE); } catch {}
}
return [{ json: { workflow_name: .name, execution_id: String(.id), status: 'skipped', skip_reason: input.skipReason, hours_since: input.hoursSince, new_sessions: input.newSessions, lock_acquired: input.lockAcquired, finished_at: new Date().toISOString(), service_identity: 'n8n-workflows', metadata: { job: 'M30-Dream' } } }];

